    "Women's Campus": "حرم البنات",
    "Main Academic": "أكاديمي رئيسي",
    "Connected to LMS": "متصل بالنظام",
    "Ashrafia Free Charitable Hospital": "مستشفى الأشرفية الخيري المجاني",
    "In addition to sacred scholarship, Jamia Ashrafia operates a full-service charitable hospital on Ferozepur Road, providing free diagnostics, outpatient care, emergency treatments, and essential medicines to thousands of underprivileged citizens daily.": "إلى جانب العلوم الشرعية، تدير الجامعة الأشرفية مستشفى خيرياً متكامل الخدمات على طريق فيروزبور، يقدم يومياً التشخيص والعيادات الخارجية والعلاج الطارئ والأدوية الأساسية مجاناً لآلاف المحتاجين.",
    "Maktaba Ashrafia & Darul Ifta": "المكتبة الأشرفية ودار الإفتاء",
    "Maktaba Ashrafia maintains tens of thousands of rare classical Islamic manuscripts, Hadith compendiums, and Fatawa volumes. Its Darul Ifta is an internationally trusted authority rendering authoritative Shariah guidance on contemporary Islamic banking, bioethics, and family law.": "تضم المكتبة الأشرفية عشرات الآلاف من المخطوطات الإسلامية النادرة ومجاميع الحديث ومجلدات الفتاوى، ودار الإفتاء فيها مرجع موثوق دولياً يقدم التوجيه الشرعي المعتمد في المصرفية الإسلامية المعاصرة وأخلاقيات الطب وأحكام الأسرة.",
    "Founded on <strong>14 September 1947</strong>, just one month following the independence of Pakistan, Jamia Ashrafia was established by the eminent scholar <strong>Hazrat Maulana Mufti Muhammad Hassan Amritsari (RA)</strong>. In recognition of the immense spiritual guidance and unwavering support for an independent Muslim homeland, the institution was named in honor of the revered Hakim al-Ummah <strong>Hazrat Maulana Ashraf Ali Thanwi (RA)</strong>.": "تأسست الجامعة الأشرفية في <strong>14 سبتمبر 1947م</strong>، بعد شهر واحد فقط من استقلال باكستان، على يد العالم الجليل <strong>فضيلة الشيخ المفتي محمد حسن الأمرتسري رحمه الله</strong>. وتقديراً لتوجيهه الروحي العظيم ودعمه الثابت لقيام وطن إسلامي مستقل، سُمّيت المؤسسة باسم حكيم الأمة <strong>الشيخ أشرف علي التهانوي رحمه الله</strong>.",
    "<strong>Nila Gumbad Anarkali (1947):</strong> Jamia Ashrafia commenced in a historic three-storied quadrangular building at Nila Gumbad in the vibrant historic center of Lahore. The initial classes quickly attracted seekers of sacred knowledge from across the subcontinent.": "<strong>نيلا غنبد أناركلي (1947م):</strong> بدأت الجامعة الأشرفية في مبنى تاريخي رباعي الأضلاع من ثلاثة طوابق في نيلا غنبد بقلب لاهور التاريخي النابض، وسرعان ما اجتذبت حلقاتها الأولى طلاب العلم الشرعي من أنحاء شبه القارة.",
    "<strong>Ferozepur Road Campus (1955-1957):</strong> On <strong>28 March 1955</strong>, a sprawling 120-kanal estate situated between Canal Road and Ferozepur Road was acquired. Construction began with the laying of the foundation stone for the central Grand Jamia Mosque. By 1957, the faculty and residential students relocated to this majestic new campus.": "<strong>حرم طريق فيروزبور (1955-1957م):</strong> في <strong>28 مارس 1955م</strong> اقتُنيت أرض واسعة مساحتها 120 كنالاً بين طريق القناة وطريق فيروزبور، وبدأ البناء بوضع حجر الأساس للجامع الكبير، وبحلول عام 1957م انتقل الأساتذة والطلاب المقيمون إلى هذا الحرم الجديد المهيب.",
    "<strong>Faculty of Hadith (1958):</strong> Teaching of classical Hadith courses was formally inaugurated in 1958 under the globally celebrated Muhaddith <strong>Hazrat Maulana Muhammad Idris Kandhlawi (RA)</strong>, author of <em>Ma'arif al-Quran</em> and <em>At-Ta'liq as-Sabih</em>.": "<strong>كلية الحديث (1958م):</strong> افتُتح تدريس كتب الحديث رسمياً عام 1958م بإشراف المحدّث الشهير <strong>الشيخ محمد إدريس الكاندهلوي رحمه الله</strong>، صاحب <em>معارف القرآن</em> و<em>التعليق الصبيح</em>.",
    "Following the passing of the founder <strong>Mufti Muhammad Hassan</strong> on 1 June 1961, institutional leadership and preservation of high academic standards were carried forward by his distinguished sons:": "بعد وفاة المؤسس <strong>المفتي محمد حسن</strong> في 1 يونيو 1961م، حمل أبناؤه الأفاضل أمانة قيادة المؤسسة والحفاظ على مستواها العلمي الرفيع:",
    "<strong>Maulana Mufti Muhammad Ubaidullah (Late):</strong> Pioneered international academic outreach.": "<strong>الشيخ المفتي محمد عبيد الله رحمه الله:</strong> رائد التواصل العلمي الدولي.",
    "<strong>Maulana Abd-ur-Rahman Ashrafi (Late):</strong> Champion of community welfare and education.": "<strong>الشيخ عبد الرحمن الأشرفي رحمه الله:</strong> رائد خدمة المجتمع والتعليم.",
    "<strong>Maulana Fazl-ur-Raheem Ashrafi:</strong> Current Principal / Mohtamim, leading modern reforms and the Cloud LMS initiative.": "<strong>الشيخ فضل الرحيم الأشرفي:</strong> المهتمم الحالي، يقود الإصلاحات الحديثة ومشروع منصة التعلم السحابية.",
    "<strong>Maulana Hafiz Ajwad Ubaid & Qari Arshad Ubaid:</strong> Guiding academic administration and Hadith discourse.": "<strong>الشيخ الحافظ أجود عبيد والقارئ أرشد عبيد:</strong> يوجّهان الإدارة الأكاديمية ودروس الحديث.",
    "<strong>Wifaq ul Madaris Equivalence:</strong> The <em>Shahadat-ul-Alimiyyah</em> degree awarded by Jamia Ashrafia under Wifaq-ul-Madaris Al-Arabia Pakistan is recognized by the Higher Education Commission (HEC) of Pakistan as equivalent to an M.A. in Islamic Studies and Arabic.": "<strong>معادلة وفاق المدارس:</strong> تعترف هيئة التعليم العالي في باكستان (HEC) بشهادة <em>العالمية</em> التي تمنحها الجامعة الأشرفية تحت وفاق المدارس العربية باكستان معادِلةً للماجستير في الدراسات الإسلامية واللغة العربية.",

