    "As the teacher, sign in when the meeting asks (Google / GitHub) to start the class as moderator.": "بصفتك المعلم، سجّل الدخول عندما يطلب الاجتماع (Google / GitHub) لبدء الحصة كمشرف.",
    "If the teacher has not started yet, wait on the meeting page — it opens automatically.": "إن لم يبدأ المعلم بعد، انتظر في صفحة الاجتماع — سيفتح تلقائياً.",
    "Passcode if asked:": "رمز الدخول عند الطلب:",
    "The live classroom opens in a new tab": "يُفتح الفصل المباشر في علامة تبويب جديدة",
    "Your attendance has been recorded. Keep this portal open in the other tab.": "تم تسجيل حضورك. أبقِ البوابة مفتوحة في علامة التبويب الأخرى.",
    "Open Live Classroom": "فتح الفصل المباشر",
