    "This person is not a Super Admin.": "هذا الشخص ليس مشرفاً عاماً.",
    "There must always be at least one Super Admin. Make someone else Super Admin first.": "يجب أن يوجد مشرف عام واحد على الأقل دائماً. عيّن شخصاً آخر أولاً.",
    "Choose the role this person will have instead.": "اختر الدور البديل لهذا الشخص.",
    "You are not allowed to create roles.": "لا يُسمح لك بإنشاء الأدوار.",
    "The role identifier must start with a letter and use only A-Z, 0-9 and _ (e.g. EXAM_OFFICER).": "يجب أن يبدأ معرّف الدور بحرف وأن يستخدم A-Z و0-9 و_ فقط (مثل EXAM_OFFICER).",
    "SUPER_ADMIN is reserved.": "SUPER_ADMIN محجوز.",
    "A role with the identifier {x} already exists.": "يوجد دور بالمعرّف {x} بالفعل.",
    "Only whole-institution staff can create a role with whole-institution scope.": "لا ينشئ دوراً بنطاق المؤسسة بأكملها إلا موظفو المؤسسة بأكملها.",
    "You are not allowed to change roles.": "لا يُسمح لك بتغيير الأدوار.",
    "Super Admin always has full access and cannot be changed.": "للمشرف العام وصول كامل دائماً ولا يمكن تغييره.",
    "Only the Super Admin can change a role you hold yourself.": "لا يغيّر الدور الذي تحمله إلا المشرف العام.",
    "Someone else changed this role while you were editing it. Reload it and make your change again.": "غيّر شخص آخر هذا الدور أثناء تعديلك. أعد تحميله وأجرِ تغييرك مجدداً.",
    "The data scope of Admin, Teacher and Student is fixed.": "نطاق بيانات المشرف والمعلم والطالب ثابت.",
    "Unknown data scope.": "نطاق بيانات غير معروف.",
    "Only whole-institution staff can give a role whole-institution scope.": "لا يمنح نطاق المؤسسة بأكملها إلا موظفو المؤسسة بأكملها.",
    "You are not allowed to delete roles.": "لا يُسمح لك بحذف الأدوار.",
    "Super Admin, Admin, Teacher and Student cannot be deleted.": "لا يمكن حذف أدوار المشرف العام والمشرف والمعلم والطالب.",
    "You cannot delete a role you hold.": "لا يمكنك حذف دور تحمله.",
    "This role can do things you cannot, so you cannot delete it.": "يستطيع هذا الدور أموراً لا تستطيعها، لذا لا يمكنك حذفه.",
    "This role holds permissions you do not have, so you cannot delete it.": "يحمل هذا الدور صلاحيات لا تملكها، لذا لا يمكنك حذفه.",
    "Your role does not use daily check-in.": "دورك لا يستخدم تسجيل الحضور اليومي.",
    "Attendance older than {n} days can only be corrected by staff with that permission.": "لا يصحح الحضور الأقدم من {n} يوماً إلا الموظفون المخوّلون.",
    "There is no role called {x}.": "لا يوجد دور باسم {x}.",
    "You cannot give the role {x}: it can do things you cannot.": "لا يمكنك إسناد الدور {x}: فهو يستطيع أموراً لا تستطيعها.",
    "You are not allowed to create this kind of account.": "لا يُسمح لك بإنشاء هذا النوع من الحسابات.",
    "This person can do things you cannot, so you cannot change their account.": "يستطيع هذا الشخص أموراً لا تستطيعها، لذا لا يمكنك تغيير حسابه.",
    "You are not allowed to activate or deactivate this account.": "لا يُسمح لك بتفعيل هذا الحساب أو تعطيله.",
    "You are not allowed to edit this account.": "لا يُسمح لك بتعديل هذا الحساب.",
    "This work has already been checked. Ask your teacher to return it for resubmission.": "تم تصحيح هذا العمل مسبقاً. اطلب من معلمك إعادته لإعادة التسليم.",
    "This assignment is not for your class.": "هذا الواجب ليس لفصلك.",
    "This exam is not for your class.": "هذا الامتحان ليس لفصلك.",
    "This exam is not open.": "هذا الامتحان غير مفتوح.",
    "This paper has already been submitted.": "سُلِّمت هذه الورقة مسبقاً.",
    "You are not allowed to publish results.": "لا يُسمح لك بنشر النتائج.",
    "You are not allowed to withdraw published results.": "لا يُسمح لك بسحب النتائج المنشورة.",
    "You are not allowed to open or close exams.": "لا يُسمح لك بفتح الامتحانات أو إغلاقها.",
    "You are not allowed to write exam papers.": "لا يُسمح لك بإعداد أوراق الامتحانات.",
    "You are not allowed to verify payments.": "لا يُسمح لك بالتحقق من المدفوعات.",
    "You are not allowed to grant waivers.": "لا يُسمح لك بمنح الإعفاءات.",
    "You are not allowed to confirm donations.": "لا يُسمح لك بتأكيد التبرعات.",
    "You are not allowed to change library fines.": "لا يُسمح لك بتغيير غرامات المكتبة.",
