    "Delete the student {name} ({roll})? They will no longer be able to sign in. Their attendance, results and fee records are kept. To keep the account, suspend it instead.": "حذف الطالب {name} ({roll})؟ لن يتمكن من تسجيل الدخول بعد ذلك. تبقى سجلات حضوره ونتائجه ورسومه محفوظة. للإبقاء على الحساب، أوقفه بدلًا من ذلك.",
    "Delete the teacher {name}? They will no longer be able to sign in, and {n} class / kitab allocation(s) and {p} timetable period(s) will be left without a teacher. To keep their history, deactivate them instead.": "حذف المدرّس {name}؟ لن يتمكن من تسجيل الدخول، وسيبقى {n} من إسنادات الفصول / الكتب و{p} من حصص الجدول بلا مدرّس. للإبقاء على سجله، عطّل الحساب بدلًا من ذلك.",
